def test_failed_optional_bootstrap_keeps_original_state_and_redacts_failures(mode, failure_kind):
    assert "browser_bootstrap_timeout" in inspect.signature(AsyncPinAuth).parameters, "bootstrap must be bounded"
    initial = BootstrapTransport(bundle=_preauth_bundle())
    entered = []
    cleaned = []

    async def provider(bundle, url):
        entered.append(url)
        try:
            if failure_kind == "exception":
                raise RuntimeError("synthetic-sensitive-browser-state")
            if failure_kind == "timeout":
                await asyncio.sleep(60)
            html = primary_html() if mode == "primary" else pin_html()
            if failure_kind == "persistent":
                html = BROWSER_CHECK_HTML
            if failure_kind == "invalid":
                html = "<html>synthetic-sensitive-browser-state</html>"
            if failure_kind == "mode":
                html = pin_html() if mode == "primary" else primary_html()
            if failure_kind == "srp":
                html = html.replace("f" * 512, "ff")
            if failure_kind == "duplicate":
                html += html
            return bootstrap_module.BrowserBootstrapResult(
                html=html, cookies=(),
                browser=BrowserProfile((("user-agent", "Synthetic Firefox"),)),
                url="https://example.org/" if failure_kind == "url" else url,
            )
        finally:
            cleaned.append(True)

    expected = {
        "exception": "browser_bootstrap_failed", "timeout": "browser_bootstrap_timeout",
        "persistent": "browser_check_required", "url": "unsupported_browser_state",
    }.get(failure_kind, "invalid_frontend_config")

    async def scenario():
        async with make_auth(mode, initial, browser_bootstrap=provider, browser_bootstrap_timeout=0.01) as auth:
            before = auth.bundle
            with pytest.raises(PinAuthError) as failure:
                await attempt(auth, mode)
            assert failure.value.code == expected
            assert failure.value.__cause__ is None and failure.value.__context__ is None
            assert "synthetic-sensitive-browser-state" not in str(failure.value)
            assert auth.bundle is before and auth._transport is initial and auth._config is None
            assert initial.calls == [("GET", AUTH_PAGE)] and not initial.closed
            tb = failure.value.__traceback__
            while tb:
                if tb.tb_frame.f_code.co_name == "login":
                    for secret in ("pin", "login", "password", "captcha_code", "audio_captcha_code"):
                        assert tb.tb_frame.f_locals.get(secret) in (None, "")
                tb = tb.tb_next
        assert entered == [AUTH_PAGE] and cleaned == [True] and initial.closed

    asyncio.run(scenario())

