def test_curl_response_honors_authoritative_samesite_without_losing_untouched_policy(
    header, value, policy, tmp_path,
):
    bundle = SessionBundle(APP_ORIGIN, APP_ORIGIN, (
        CookieRecord("fixture", "synthetic", "online.sberbank.ru", same_site="Strict"),
        CookieRecord("untouched", "synthetic", "online.sberbank.ru", path="/CSAFront", same_site="Lax"),
    ))
    store = [native_cookie("untouched", "synthetic", "/CSAFront")]
    if value is not None:
        store.append(native_cookie("fixture", value))
    if header and header.startswith("unrelated="):
        store.append(native_cookie("unrelated", "synthetic"))
    if header and "Path=/CSAFront" in header:
        store.append(native_cookie("fixture", "other-scope", "/CSAFront"))
    raw_headers = b"HTTP/2 200 OK\r\n"
    if header:
        raw_headers += b"Set-Cookie: " + header.encode() + b"\r\n"
    raw_headers += b"\r\n"

    async def scenario():
        transport = CurlAsyncTransport(bundle, require_ready=False)
        try:
            transport._session._parse_response(
                SyntheticCurl(store), BytesIO(b"synthetic document"), BytesIO(raw_headers),
                "utf-8", discard_cookies=False,
            )
            snapshot = bundle.with_cookie_jar(transport.cookie_jar())
            records = {(cookie.name, cookie.path): cookie for cookie in snapshot.cookies}
            assert records[("untouched", "/CSAFront")].same_site == "Lax"
            if value is None:
                assert ("fixture", "/") not in records
            else:
                assert records[("fixture", "/")].value == value
                assert records[("fixture", "/")].same_site == policy
            if header and "Path=/CSAFront" in header:
                assert records[("fixture", "/CSAFront")].same_site is None
            path = tmp_path / "synthetic-curl-state.json"
            snapshot.save(path)
            assert SessionBundle.load(path).cookies == snapshot.cookies
        finally:
            await transport.aclose()

    asyncio.run(scenario())

