def _server_challenge(client_a: int, pin: str) -> tuple[str, str, str, str]:
    n = int(N_HEX, 16)
    g = 2
    salt = int("deadbeefcafebabe", 16)
    private_b = int("aabbccddeeff0011", 16)
    width = (n.bit_length() + 7) // 8

    def integer_bytes(value: int) -> bytes:
        return value.to_bytes(max(1, (value.bit_length() + 7) // 8), "big")

    def pad(value: int) -> bytes:
        return integer_bytes(value).rjust(width, b"\0")

    def digest(*parts: bytes) -> bytes:
        result = hashlib.sha512()
        for part in parts:
            result.update(part)
        return result.digest()

    def digest_int(*parts: bytes) -> int:
        return int.from_bytes(digest(*parts), "big")

    k = digest_int(pad(n), pad(g))
    x = digest_int(integer_bytes(salt), pin.encode())
    verifier = pow(g, x, n)
    server_b = (k * verifier + pow(g, private_b, n)) % n
    u = digest_int(pad(client_a), pad(server_b))
    shared = pow((client_a * pow(verifier, u, n)) % n, private_b, n)
    session_hash = digest(pad(shared))
    h_n = digest(integer_bytes(n))
    h_g = digest(integer_bytes(g))
    m1 = digest(
        bytes(left ^ right for left, right in zip(h_n, h_g, strict=True)),
        integer_bytes(salt),
        pad(client_a),
        pad(server_b),
        session_hash,
    )
    m1_int = int.from_bytes(m1, "big")
    m2 = digest(pad(client_a), integer_bytes(m1_int), session_hash)
    return format(server_b, "x"), format(salt, "x"), format(m1_int, "x"), format(int.from_bytes(m2, "big"), "x")

