def __init__(self, payload, status_code=200):
        self.payload = payload
        self.status_code = status_code
        self.headers = {"content-type": "application/json"}

def post(self, url, **kwargs):
        self.calls.append((url, kwargs))
        return self.responses.pop(0)

def har_entry(path, *, cookies=None, request_headers=None, response_cookies=None):
    return {
        "request": {
            "method": "POST",
            "url": f"https://web-node2.online.sberbank.ru{path}",
            "headers": request_headers or [],
            "cookies": cookies or [],
        },
        "response": {"headers": [], "cookies": response_cookies or [], "content": {}},
    }

def getinfo(self, info):
        if info == CurlInfo.COOKIELIST:
            return self.cookies
        if info == CurlInfo.EFFECTIVE_URL:
            return (APP_ORIGIN + "/CSAFront/index.do").encode()
        if info in (CurlInfo.PRIMARY_IP, CurlInfo.LOCAL_IP, CurlInfo.REDIRECT_URL):
            return b""
        if info == CurlInfo.RESPONSE_CODE:
            return 200
        return 0
